node --input-type=module <<'EOF'
import {createRequire} from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--enable-unsafe-swiftshader']});
const page=await browser.newPage({viewport:{width:1280,height:800}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:8765/index.html');
await page.locator('#start').click();
const read=()=>page.evaluate(()=>({x:player.x,y:player.y,mask:player.mask,hp:player.hp,rocks:rocks.length,got:essences.filter(e=>e.got).length,dialogue:!!dialogue,toast:document.querySelector('#toast').textContent}));
console.log('start',await read());
await page.keyboard.down('d');await page.waitForTimeout(500);await page.keyboard.up('d');console.log('move',await read());
await page.keyboard.press('2');await page.keyboard.press('Space');await page.waitForTimeout(80);console.log('goron action',await read());
await page.keyboard.press('3');await page.keyboard.press('Space');console.log('zora action',await read());
await page.locator('[data-dir="up"]').dispatchEvent('pointerdown',{pointerId:1});await page.waitForTimeout(150);await page.locator('[data-dir="up"]').dispatchEvent('pointerup',{pointerId:1});console.log('mobile directional simulated',await read());
console.log('errors',errors);
await browser.close();
EOF

